(() => {
'use strict';
function create(ui) {
  const track = (event, target) => globalThis.FactorioAnalytics?.track(event, target);
  const { catalog, library, community, production, atlas, esc, image, svg, number, heading, searchField, empty, showModal, notify, addRows, renderPage, download } = ui;
  const goods = new Map([...catalog.items, ...catalog.fluids, ...atlas.coverage.items.filter(i => i.internal)].map(i => [i.id, i]));
  const recipes = new Map(production.recipes.map(r => [r.id, r]));
  const name = id => goods.get(id)?.name || id.replaceAll('-', ' ');
  const s = { coverageQuery: '', coverageGroup: 'All', query: '', category: 'All', source: 'All', kind: 'All', direction: 'all', page: 0, targets: [{ id: 'solar-panel', count: 100 }, { id: 'accumulator', count: 84 }, { id: 'substation', count: 8 }], boundary: 'raw', supplied: [], fromBlueprint: '', planNote: '', error: '' };
  const STARTER_COLLECTION = 'Early game · no robots';
  const TRANSPORT_COLLECTION = 'Transport workshops';
  const SCIENCE_COLLECTION = 'Science factories';
  const POWER_COLLECTION = 'Electric power workshops';
  if (new URLSearchParams(location.search).get('collection') === 'early-game') Object.assign(s, {source: STARTER_COLLECTION, direction: 'outputs'});
  if (new URLSearchParams(location.search).get('collection') === 'transport') Object.assign(s, {source: TRANSPORT_COLLECTION, direction: 'outputs'});
  if (new URLSearchParams(location.search).get('collection') === 'science-factories') Object.assign(s, {source: SCIENCE_COLLECTION, direction: 'outputs'});
  if (new URLSearchParams(location.search).get('collection') === 'power-workshops') Object.assign(s, {source: POWER_COLLECTION, direction: 'outputs'});
  const PAGE_SIZE = 24;
  const productsOf = b => [...new Set([...((b.workshop || b.scienceFactory) ? b.products : []), ...(b.analysis.outputs || []), ...(b.analysis.netOutputs || []), ...(b.products || [])])];
  const byId = new Map(library.blueprints.map(b => [b.id, b]));
  let displayedBlueprint;
  function refreshBlueprints() {
    byId.clear();
    for (const blueprint of library.blueprints) byId.set(blueprint.id, blueprint);
  }
  function save() { try { localStorage.setItem('factorio-production-v1', JSON.stringify({ targets: s.targets, boundary: s.boundary, supplied: s.supplied, fromBlueprint: s.fromBlueprint, planNote: s.planNote })); } catch {} }
  try {
    const saved = JSON.parse(localStorage.getItem('factorio-production-v1') || 'null');
    if (saved && Array.isArray(saved.targets) && saved.targets.length <= 100 && saved.targets.every(t => goods.has(t.id) && Number.isSafeInteger(t.count) && t.count > 0 && t.count <= 1000000)) {
      s.targets = saved.targets;
      s.boundary = ['raw', 'plates', 'blueprint'].includes(saved.boundary) ? saved.boundary : 'raw';
      s.supplied = (Array.isArray(saved.supplied) ? saved.supplied : []).filter(id => goods.has(id));
      s.fromBlueprint = typeof saved.fromBlueprint === 'string' ? saved.fromBlueprint : '';
      s.planNote = typeof saved.planNote === 'string' ? saved.planNote : '';
    }
  } catch {}
  const tokens = (ids, limit = Infinity, clickable = false) => ids.slice(0, limit).map(id => `<${clickable ? 'button' : 'span'} class="product-token" title="${esc(name(id))}"${clickable ? ` data-action="product-path" data-id="${esc(id)}"` : ''}>${image(id)}<span>${esc(name(id))}</span></${clickable ? 'button' : 'span'}>`).join('') + (ids.length > limit ? `<span class="more-token">+${ids.length - limit}</span>` : '');
  const options = (values, selected) => values.map(value => `<option value="${esc(value)}" ${value === selected ? 'selected' : ''}>${esc(value)}</option>`).join('');
  const matches = (text, query) => query.toLowerCase().replace(/\bbots?\b/g, 'robot').split(/[^a-z0-9]+/).filter(Boolean).every(word => text.toLowerCase().replaceAll('-', ' ').includes(word) || (word.endsWith('s') && text.toLowerCase().includes(word.slice(0, -1))));
  function filteredBlueprints() {
    return library.blueprints.filter(b => {
      const a = b.analysis;
      const search = s.direction === 'outputs' ? [b.colour || '', ...productsOf(b).map(id => name(id) + ' ' + id)].join(' ') : s.direction === 'inputs' ? a.inputs.map(id => name(id) + ' ' + id).join(' ') : [b.name, b.section, b.category, b.file, a.kind, ...productsOf(b), ...a.inputs, ...b.entries.map(r => r.id)].join(' ');
      return (s.source === 'All' || b.collection === s.source) && (s.category === 'All' || b.category === s.category) && (s.kind === 'All' || a.kind === s.kind) && matches(search, s.query);
    }).sort((a, b) => {
      if (a.starter || b.starter) return (a.starter ? -1 : 0) - (b.starter ? -1 : 0) || (a.order || 0) - (b.order || 0);
      if (a.workshop && b.workshop) return a.order - b.order;
      const score = b => b.section === 'Solar, Accumulators, and Substations' ? 0 : b.section === 'Robots' ? 1 : b.category === 'Power' ? 2 : 3;
      return score(a) - score(b);
    });
  }
  function coveragePage() {
    const coverage = atlas.coverage;
    const filtered = coverage.items.filter(i => (s.coverageGroup === 'All' || i.group === s.coverageGroup) && matches(i.name + ' ' + i.id, s.coverageQuery));
    const tested = atlas.blueprints.filter(b => b.validation?.status === 'game-tested').length;
    return `${heading('A BUILD FOR EVERY RECIPE PRODUCT', 'Every craftable item', 'Find a layout, collect its construction materials, and plan the supplies that keep it running.', '<a class="button secondary" href="#blueprints">All blueprints '+svg('arrow')+'</a>')}
      <section class="coverage-summary"><div><strong>${coverage.covered}<span> / ${coverage.total}</span></strong><p>craftable items have a production blueprint</p></div><div><b>${tested} game-tested layouts</b><p>Starter builds and recipe cells have native checks. Other community layouts have recipe reviews.</p></div></section>
      <p class="small muted">Scope: inventory items with a recipe in Factorio ${esc(catalog.version)} / Space Age, plus silo rocket parts. Includes random-yield recycling and breeding. Quality variants share a recipe. Mining-only resources and editor tools are listed separately below.</p>
      <div class="explorer-search">${searchField('coverage-search', 'Find an item to produce…', s.coverageQuery)}<select id="coverage-group" aria-label="Filter item group">${options(['All', ...new Set(coverage.items.map(i => i.group))].filter(Boolean), s.coverageGroup)}</select></div>
      <div class="results-heading"><span>${filtered.length} items</span><span>${coverage.missing.length ? coverage.missing.length + ' NEED A BUILD' : 'COMPLETE RECIPE COVERAGE'}</span></div>
      <div class="coverage-grid">${filtered.map(i => { const b = byId.get(i.builds[0]); return `<article class="coverage-item" data-product="${esc(i.id)}"><div class="coverage-product">${image(i.id)}<div><h3>${esc(i.name)}</h3><small>${esc(i.group)} · ${i.builds.length} matching ${i.builds.length === 1 ? 'build' : 'builds'}</small></div></div>${b ? `<p>${esc(b.name)}</p><span class="tag">${b.validation?.status === 'game-tested' ? 'Game tested' : 'Recipe matched'}</span><div class="coverage-actions"><button class="button primary compact" data-action="blueprint-details" data-id="${b.id}">Open blueprint ${svg('arrow')}</button><button class="text-button" data-action="product-path" data-id="${esc(i.id)}">Recipes & alternatives</button></div>` : '<p class="amber-text">No matching production layout yet.</p>'}${i.note ? `<p class="small muted">${esc(i.note)}</p>` : ''}</article>`; }).join('')}</div>
      ${!filtered.length ? empty('No matching items', 'Try another item name or clear the group filter.') : ''}
      <details class="explorer-details"><summary>Items without crafting recipes <span>${coverage.nonCraftable.length} extraction resources, tools, and special items</span></summary><div class="token-wrap">${coverage.nonCraftable.map(i => `<span class="product-token" title="${esc(i.reason)}">${image(i.id)}<span>${esc(i.name)}</span></span>`).join('')}</div><p class="small muted">Obtain these through mining, harvesting, platform collection, scenario rewards, or game tools. No manufacturing recipe is available in this catalogue.</p></details>
      <details class="explorer-details"><summary>Collection credits <span>Original authors and downloadable books</span></summary><ul><li><a href="${esc(community.source)}" target="_blank" rel="noopener">Autosaved · original collection</a></li>${atlas.sources.map(source => `<li><a href="${esc(source.url)}" target="_blank" rel="noopener">${esc(source.author)} · ${esc(source.id.replaceAll('-', ' '))}</a> · <a href="sources/collections/${esc(source.id)}.txt" download>Download book</a></li>`).join('')}</ul><p class="small muted">Generated recipe cells are original additions. The source collections retain their authorship.</p></details>`;
  }
  const previewURL = b => b.rawOnly && b.validation?.blueprintSha256 ? b.preview + '?v=' + b.validation.blueprintSha256.slice(0, 12) : b.preview;
  const rateNumber = value => !Number.isFinite(value) ? 'Not measured' : value > 0 && value < .01 ? '<0.01' : new Intl.NumberFormat(undefined, {maximumFractionDigits: 2}).format(value);
  function blueprintRates(b, compact = false) {
    const measured = b.benchmark;
    if (!measured?.perMinute) return '';
    const inputs = [...new Set(b.rawInputs || b.analysis.inputs)], outputs = [...new Set([...(b.products || []), ...(b.sideProducts || [])])];
    const rows = (ids, values, output) => ids.map(id => `<tr data-rate-item="${esc(id)}"><th scope="row">${image(id)}<span>${esc(name(id))}${output && b.sideProducts?.includes(id) ? ' <small>(byproduct)</small>' : ''}</span></th><td>${esc(rateNumber(values?.[id]))}<small>${goods.get(id)?.type === 'fluid' ? 'fluid/min' : 'items/min'}</small></td></tr>`).join('');
    const table = (label, ids, values, cls, output = false) => `<div><h4>${label}</h4><table class="rate-table ${cls}" aria-label="${label} per minute"><tbody>${rows(ids, values, output)}</tbody></table></div>`;
    return `<section class="blueprint-rates ${compact ? 'card-rates' : 'throughput-results'}" aria-label="Measured input and output rates"><${compact ? 'h4' : 'h3'}>Measured per minute</${compact ? 'h4' : 'h3'}><div class="rate-columns">${table('Inputs consumed', inputs, measured.inputPerMinute, 'input-rates')}${table('Outputs collected', outputs, measured.perMinute, 'output-rates', true)}</div>${compact ? '<p class="small muted">Raw supply + external power. All outputs collected.</p>' : `<p>Average rates on this exact layout in Factorio ${esc(measured.gameVersion)}: ${measured.warmupMinutes} minutes to warm up, then ${measured.measuredMinutes} minutes measured. All outputs were collected continuously.</p><p class="small muted">Input consumption includes furnace fuel. Fluids use fluid units per minute. Startup needs extra stock to fill belts and pipes. Intermediate buffers can still fill during the test; rates change when inputs run short or outputs back up.</p><a class="source-link" href="${esc(measured.report)}" target="_blank" rel="noopener">Read the throughput test ↗</a>${b.reviewReport ? ` · <a class="source-link" href="${esc(b.reviewReport)}" target="_blank" rel="noopener">Design and tuning review ↗</a>` : ''}`}</section>`;
  }
  function blueprintCard(b) {
    const a = b.analysis;
    return `<article class="blueprint-card explorer-card"><button class="layout-link" data-action="blueprint-details" data-id="${b.id}" aria-label="Explore ${esc(b.name)}">${b.preview ? `<img class="layout-preview" src="${esc(previewURL(b))}" alt="Entity layout of ${esc(b.name)}" loading="lazy" width="640" height="400">` : `<div class="layout-placeholder">${b.icons.slice(0, 4).map(id => image(id)).join('')}</div>`}<span class="layout-badge">${esc(a.kind)}</span></button><div class="blueprint-content"><div class="blueprint-origin">${esc(b.collection)} <span> / ${esc(b.category)}</span></div><h3>${esc(b.name)}</h3><p class="blueprint-section">${esc(b.section || b.file)}${b.edition ? ` · ${esc(b.edition)}` : ''}</p>${b.rawOnly ? `<p class="starter-requires">Requires ${b.requires.map(id => esc(id.replaceAll('-', ' '))).join(' + ')}</p>` : ''}<div class="card-products"><span class="micro-label">${productsOf(b).length ? 'PRODUCES' : 'PROVIDES'}</span>${productsOf(b).length ? tokens(productsOf(b), 3) : `<p>${esc(a.serviceOutputs[0] || 'A collection of layouts')}</p>`}</div>${b.rawOnly ? `<div class="card-products"><span class="micro-label">RAW INPUTS · EXTERNAL POWER</span>${a.inputs.length ? tokens(a.inputs, 4) : `<p>${b.kind === 'mining' ? 'Resource patch + electricity' : 'Items on the incoming belt'}</p>`}</div>` : ''}<div class="blueprint-metrics">${b.footprint ? `<span>${b.footprint.width} × ${b.footprint.height} tiles</span>` : ''}<span>${number(b.entityCount)} entities</span><span>${b.isBook ? b.blueprintCount + ' layouts' : a.recipes.length + ' recipes'}</span></div><div class="blueprint-actions"><button class="button secondary compact" data-action="blueprint-details" data-id="${b.id}">Inputs & outputs ${svg('arrow')}</button><button class="text-button amber-text" data-action="pack-blueprint" data-id="${b.id}">Pack build</button></div>${blueprintRates(b, true)}</div></article>`;
  }
  function starterBanner() {
    const starters = library.blueprints.filter(b => b.starter);
    const stages = (atlas.starterResearch?.stages || []).filter(stage => stage.modules.length);
    const active = s.source === STARTER_COLLECTION;
    return `<section class="collection-banner starter-banner"><div class="collection-symbols">${image('iron-ore')}${image('copper-ore')}${image('coal')}</div><div><span class="eyebrow">EARLY GAME · RAW MATERIALS ONLY</span><h2>Add a module after each research unlock.</h2><p>${starters.length} independent production modules across ${stages.length} research stages. Each includes smelting and every intermediate. Supply raw materials and external power; collect the finished item.</p><p class="small muted">Uses assembling machine 2, steel furnaces, and big and medium electric poles. Research Automation 2, Advanced material processing and Electric energy distribution 1; all need red and green science. Connect power to the big pole marked P. Each card lists its requirements. Wood feeds wooden items, and oil-stage modules take crude oil. No robots or intermediate deliveries.</p></div><div class="starter-actions">${!active ? `<button class="button primary compact" data-action="explore-feature" data-id="early-game">Show raw-input modules ${svg('arrow')}</button>` : '<span class="tag">GROUPED BY RESEARCH UNLOCK</span>'}<a class="button secondary compact" href="sources/collections/early-game.txt" download>Download starter book ${svg('download')}</a></div></section>${active ? `<details class="starter-roadmap"><summary>Choose a research unlock <span>${stages.length} research packs</span></summary><p class="small muted">Each pack groups modules by their latest required technology. Complete every research branch listed on the card, including the upgraded machine unlocks. Technologies that only improve stats need no production module.</p><div class="research-stage-grid">${stages.map(stage => `<div class="research-stage"><button class="text-button" data-action="starter-unlock" data-id="${esc(stage.id)}"><img class="game-icon" src="${esc(catalog.technologies.find(t => t.id === stage.id)?.icon || 'assets/icons/automation-science-pack.png')}" alt="" loading="lazy" width="28" height="28"><span>${esc(stage.name)}<small>${stage.modules.length} module${stage.modules.length === 1 ? "" : "s"}</small></span></button><a href="sources/early-game/unlocks/${esc(stage.id)}.txt" class="source-link" download aria-label="Download ${esc(stage.name)} research pack">${svg('download')}</a></div>`).join('')}</div></details>` : ''}`;
  }
  function collectionBanner() {
    if (s.source === SCIENCE_COLLECTION) return `<section class="collection-banner starter-banner"><div class="collection-symbols">${['automation-science-pack', 'logistic-science-pack', 'military-science-pack', 'chemical-science-pack'].map(id => image(id)).join('')}</div><div><span class="eyebrow">SCIENCE · RAW MATERIALS ONLY</span><h2>Four sciences from one factory.</h2><p>Designed for 30 of each science pack per minute. Connect iron ore, copper ore, coal, stone, water and crude oil on the left; collect science on the right. Choose the steel-furnace version with internally produced solid fuel, or the electric-furnace version.</p><p class="small muted">Fast transport belts, underground belts and splitters; assembling machine 2. Supply external electricity at P. Measured rates and construction costs are shown for each version.</p></div></section>`;
    if (s.source === POWER_COLLECTION) return `<section class="collection-banner starter-banner"><div class="collection-symbols">${['medium-electric-pole', 'big-electric-pole', 'substation', 'solar-panel'].map(id => image(id)).join('')}</div><div><span class="eyebrow">POWER EQUIPMENT · RAW MATERIALS ONLY</span><h2>Build your electric network from ore.</h2><p>One combined workshop makes medium poles, big poles and substations. Separate solar panel factories use assembling machine 2 or 3. Each includes electric smelting and every intermediate.</p><p class="small muted">Connect the labeled raw inputs and external electricity at P. No robots or furnace fuel. Each card lists its research, inputs and measured outputs.</p></div><div class="starter-actions"><a class="button secondary compact" href="sources/collections/power-workshops.txt" download>Download power workshop book ${svg('download')}</a></div></section>`;
    if (s.source !== TRANSPORT_COLLECTION) return starterBanner();
    const workshops = library.blueprints.filter(blueprint => blueprint.workshop).sort((a, b) => (a.order || 0) - (b.order || 0));
    const colours = workshops.map(blueprint => blueprint.colour).filter(Boolean);
    const colourText = colours.length ? colours.map(colour => colour.toLowerCase()).join(', ').replace(/, ([^,]+)$/, ' and $1') : 'Published colours';
    const icons = workshops.map(blueprint => productsOf(blueprint)[0]).filter(Boolean);
    const has = colour => colours.some(value => value.toLowerCase() === colour.toLowerCase());
    const specialInputs = [
      has('Blue') ? 'Blue adds water and crude oil.' : '',
      has('Green') ? 'Green adds tungsten ore, calcite and foundries on Vulcanus.' : ''
    ].filter(Boolean).join(' ');
    const byproducts = workshops.filter(blueprint => blueprint.sideProducts?.includes('solid-fuel')).map(blueprint => blueprint.colour?.toLowerCase()).filter(Boolean);
    const byproductText = byproducts.length ? ` Collect the solid-fuel byproduct from ${byproducts.join(' and ')} too.` : '';
    return `<section class="collection-banner starter-banner"><div class="collection-symbols">${(icons.length ? icons : ['transport-belt']).map(id => image(id)).join('')}</div><div><span class="eyebrow">TRANSPORT WORKSHOPS · RAW MATERIALS ONLY</span><h2>One workshop per belt colour.</h2><p>${esc(colourText)}: each workshop makes its belts, underground belts and splitters together. Shared smelting and intermediate production run from labeled raw-material inputs and external power.</p><p class="small muted">Assembling machine 2, steel furnaces, big and medium electric poles, and no robots. Circuit network is required for the circulating belts.${specialInputs ? ` ${specialInputs}` : ''}${byproductText} Each card lists all research and connections.</p></div><div class="starter-actions"><a class="button secondary compact" href="sources/collections/transport-workshops.txt" download>Download transport book ${svg('download')}</a></div></section>`;
  }
  function blueprintsPage() {
    const filtered = filteredBlueprints(), pages = Math.max(1, Math.ceil(filtered.length / PAGE_SIZE));
    s.page = Math.min(s.page, pages - 1);
    return `${heading('UNDERSTAND IT. BUILD IT. FEED IT.', 'Blueprint library', 'Explore complete layouts and the ingredients that keep them running.', '<a class="button primary" href="#production">Production planner '+svg('arrow')+'</a>')}${collectionBanner()}<a class="coverage-link" href="#coverage">${svg('check')} ${atlas.coverage.covered} / ${atlas.coverage.total} craftable items covered ${svg('arrow')}</a><div class="featured-builds">${[['early-game', 'stone-furnace', 'Early game · no robots'], ['transport', 'fast-transport-belt', 'Transport workshops'], ['solar', 'solar-panel', 'Solar factory'], ['robots', 'construction-robot', 'Robots'], ['power', 'accumulator', 'Power & storage'], ['science-factories', 'chemical-science-pack', 'Science factories'], ['power-workshops', 'substation', 'Electric power workshops'], ['science', 'automation-science-pack', 'All science'], ['all', 'blueprint-book', 'All builds']].filter(([id]) => (id !== 'science-factories' || library.blueprints.some(b => b.collection === SCIENCE_COLLECTION)) && (id !== 'power-workshops' || library.blueprints.some(b => b.collection === POWER_COLLECTION))).map(([id, icon, title]) => `<button class="feature-link" data-action="explore-feature" data-id="${id}">${image(icon)}${title}</button>`).join('')}</div><div class="explorer-search">${searchField('blueprint-search', 'Search iron, belts, circuits, robots…', s.query)}<select id="blueprint-direction" aria-label="Search blueprint field"><option value="all" ${s.direction === 'all' ? 'selected' : ''}>Search everything</option><option value="outputs" ${s.direction === 'outputs' ? 'selected' : ''}>Produces this item</option><option value="inputs" ${s.direction === 'inputs' ? 'selected' : ''}>Needs this input</option></select></div><div class="explorer-filters"><label>Collection<select id="blueprint-source">${options(['All', ...new Set(library.blueprints.map(b => b.collection))], s.source)}</select></label><label>${s.source === STARTER_COLLECTION ? 'Research unlock' : 'Section'}<select id="blueprint-category">${options(['All', ...new Set(library.blueprints.filter(b => s.source === 'All' || b.collection === s.source).map(b => b.category))].sort((a, b) => a === 'All' ? -1 : b === 'All' ? 1 : a.localeCompare(b)), s.category)}</select></label><label>Purpose<select id="blueprint-kind">${options(['All', ...new Set(library.blueprints.map(b => b.analysis.kind))], s.kind)}</select></label><button class="text-button" data-action="explore-feature" data-id="all">Reset filters</button></div><div class="results-heading"><span>${number(filtered.length)} builds · page ${s.page + 1} of ${pages}</span><span>AVAILABLE OFFLINE</span></div><div class="blueprint-grid explorer-grid">${filtered.slice(s.page * PAGE_SIZE, (s.page + 1) * PAGE_SIZE).map(blueprintCard).join('')}</div>${!filtered.length ? empty('No matching blueprints', 'Clear a filter, or search for an item such as solar panel or construction robot.') : ''}<div class="explorer-pagination"><button class="button secondary" data-action="blueprint-page" data-id="-1" ${!s.page ? 'disabled' : ''}>← Previous</button><span>${s.page + 1} / ${pages}</span><button class="button secondary" data-action="blueprint-page" data-id="1" ${s.page + 1 >= pages ? 'disabled' : ''}>Next →</button></div><p class="small muted">Layout maps are schematic previews of saved entity positions. Recipe explainers use your installed Factorio ${esc(catalog.version)} data. Books include alternative layouts; review them before packing.</p>`;
  }
  function recipeMarkup(r, count) {
    const machines = Object.entries(production.entities).filter(([id, e]) => goods.has(id) && e.categories?.includes(r.category)).map(([id]) => name(id));
    const side = parts => parts.map(p => `<span class="recipe-ingredient">${image(p.id)}<span>${number(p.amount)} ${esc(name(p.id))}${p.type === 'fluid' ? ' <small>fluid</small>' : ''}${p.probability !== 1 ? ` <small>· ${number(p.probability * 100)}% chance</small>` : ''}${p.temperature ? ` <small>· ${p.temperature}°C</small>` : ''}</span></span>`).join('');
    return `<div class="recipe-explainer"><div class="section-heading"><h3>${esc(name(r.id))}</h3><span class="tag">${count ? count + ' configured machines' : r.time + ' s base recipe'}</span></div><div class="recipe-equation"><div>${side(r.ingredients) || '<span>No item ingredients</span>'}</div>${svg('arrow')}<div>${side(r.results)}</div></div><p class="small muted">Per craft · ${number(r.time)} seconds at crafting speed 1 · ${machines.length ? 'Make in: ' + machines.map(esc).join(', ') : esc(r.category)}${r.surface?.length ? ' · Surface conditions apply' : ''}</p></div>`;
  }
  const supplyIds = a => [...new Set([...a.inputs, ...a.seeds])].filter(id => goods.has(id));
  const supplyBatch = id => ({ id, count: Math.max(1, Math.ceil(recipes.get(production.defaults[id])?.results.find(p => p.id === id)?.amount || 1)) });
  function supplyHelp(id, startup = false) {
    if (id === 'fusion-power-cell') return 'Replenish reactor fuel through the requester chests. Logistic robots need powered roboport coverage and fuel in provider or storage chests; you can also fill the requesters by hand.';
    if (id === 'fluoroketone-cold' && startup) return 'Charge every coolant circuit before starting. Cooling plants recycle the hot return fluid. Make fresh coolant upstream, then pipe it in or transport barrels and unbarrel them into the circuit.';
    if (startup) return 'Provide an initial stock and keep it circulating. The required charge depends on the connected layout.';
    if (goods.get(id)?.type === 'fluid') return 'Deliver by pipe or fluid wagon. Robots carry filled barrels, not loose fluids; add an unbarrelling assembler if using barrels.';
    return recipes.has(production.defaults[id]) ? 'Make this upstream and deliver it to the layout using its saved belts, inserters, or requester chests.' : 'Obtain this from mining, harvesting, or a suitable resource deposit and deliver it to the layout.';
  }
  const supplyTargets = b => supplyIds(b.analysis).map(id => b.startup?.targets.find(t => t.id === id) || supplyBatch(id));
  function operatingGuide(b) {
    const ids = supplyIds(b.analysis);
    if (!ids.length || b.isBook) return '';
    return `<section class="operating-guide"><h3 class="explainer-heading">Make its operating supplies</h3><p class="muted">These keep the layout running. Click a supply for matching blueprints, or plan its full recipe chain from raw resources. ${b.startup ? 'The planner starts with the tested stock below. Fuel needs replenishing; coolant circulates after the initial charge.' : 'Plans start with one recipe batch per supply; adjust quantities to the stock you want. They do not estimate a production rate or coolant fill volume.'}</p>${b.startup ? `<div class="notice"><div><strong>Tested starting stock</strong><p>${b.startup.targets.map(t => `${number(t.count)} ${esc(name(t.id))}${goods.get(t.id)?.type === 'fluid' ? ' fluid units' : ' items'}`).join(' · ')}</p><p class="small">${esc(b.startup.note)}</p><a class="source-link" href="${esc(b.startup.report)}" target="_blank" rel="noopener">View in-game test report ↗</a></div></div>` : ''}<div class="supply-grid">${ids.map(id => {
      const r = recipes.get(production.defaults[id]), startup = b.analysis.seeds.includes(id);
      return `<article class="supply-card"><span class="micro-label">${startup ? 'STARTUP / CIRCULATING STOCK' : 'ONGOING SUPPLY'}</span><button class="supply-title" data-action="product-path" data-id="${esc(id)}">${image(id)}${esc(name(id))} ${svg('arrow')}</button><p>${esc(supplyHelp(id, startup))}</p>${r ? recipeMarkup(r) : '<p class="small muted">No deterministic crafting recipe selected. Supply from extraction or a separate process.</p>'}<button class="button secondary compact" data-action="plan-supply" data-id="${esc(id)}">Plan from raw resources ${svg('arrow')}</button></article>`;
    }).join('')}</div>${b.entries.some(r => r.id === 'requester-chest') && !b.entries.some(r => r.id === 'roboport') ? `<div class="delivery-support"><h4>Robot delivery support</h4><p class="small muted">Connect the requesters to your existing powered logistics network. To extend it, click an item for its recipe and matching blueprints.</p><div class="token-wrap">${tokens(['roboport', 'logistic-robot', 'passive-provider-chest'], Infinity, true)}</div></div>` : ''}</section>`;
  }
  function blueprintDialog(b) {
    displayedBlueprint = b;
    track('blueprint_open', b.id);
    const a = b.analysis;
    const column = (label, ids, extra, cls = '') => `<section class="flow-column ${cls}"><div class="eyebrow">${label}</div><div class="flow-products">${tokens(ids, Infinity, true)}</div>${extra.length ? `<ul class="service-list">${extra.map(t => `<li>${esc(t)}</li>`).join('')}</ul>` : ''}${!ids.length && !extra.length ? '<p class="small muted">No fixed recipe products identified.</p>' : ''}</section>`;
    showModal(b.name, `<div class="blueprint-explainer">
      <div class="explainer-intro">${b.preview ? `<img class="detail-layout" src="${esc(previewURL(b))}" alt="Schematic entity layout for ${esc(b.name)}" width="640" height="400">` : ''}<div><span class="tag">${esc(a.kind)}</span><h3>${esc(b.section || b.name)}</h3><p>${esc(b.collection)} · ${esc(b.category)}${b.edition ? ` · ${esc(b.edition)}` : ''}</p><p>${b.footprint ? `${b.footprint.width} × ${b.footprint.height} tiles · ` : ''}${number(b.entityCount)} entities · ${a.recipes.length} distinct configured recipes</p>${b.preview ? `<p class="small muted">${b.rawOnly ? 'Item and fluid displays mark each input in-game. Feed the belt or pipe directly below its display from the left; press Alt for labels. ' + ((b.workshop || b.scienceFactory) ? 'Green numbered markers identify the separate output chests.' : 'Green O markers show outputs.') : 'Schematic: gold machines, blue pipes, green logistics, violet power. Orientation and connections should be checked in-game.'}</p>` : ''}
      <div class="explainer-buttons"><button class="button secondary compact" data-action="copy-blueprint" data-id="${b.id}">${svg('copy')} Copy blueprint</button>${b.entries.length && !b.isBook && !b.excluded.length ? `<button class="button primary compact" data-action="crate-blueprint" data-id="${b.id}">${svg('box')} Create construction crate</button>` : ''}${supplyIds(a).length && !b.isBook ? `<button class="button secondary compact" data-action="plan-blueprint-inputs" data-id="${b.id}">Plan operating supplies ${svg('arrow')}</button>` : ''}${productsOf(b).length && !b.isBook ? `<button class="button secondary compact" data-action="plan-blueprint" data-id="${b.id}">Plan its products ${svg('arrow')}</button>` : ''}</div></div></div>
      ${b.isBook ? '<div class="notice amber-notice">This book contains alternative layouts. The recipe overview combines them; they are not one connected factory.</div>' : ''}
      ${b.validation ? `<div class="notice validation-note"><div><strong>${b.validation.status === 'game-tested' ? (b.rawOnly ? 'Layout tested in Factorio' : 'Production tested in Factorio') : 'Community import · recipe review'}</strong><p>${esc(b.validation.note)}</p>${b.rawOnly && Number.isFinite(b.validation.firstOutputSeconds) ? `<p>First ${b.workshop ? 'transport ' : ''}output from an empty start in the test: <strong>${b.validation.firstOutputSeconds < 60 ? b.validation.firstOutputSeconds + " seconds" : (b.validation.firstOutputSeconds / 60).toFixed(1) + " minutes"}</strong>. Larger recipes can take longer to start with these small smelting lines.</p>` : ""}${b.author ? `<p>Blueprint author: ${esc(b.author)}</p>` : ''}</div></div>` : ''}${b.parameterized ? '<p class="notice amber-notice">Parameterized template: choose its recipe and settings when placing it. It is not counted as a fixed product layout.</p>' : ''}${b.setupNotes?.length ? `<section class="cell-setup"><h3>${b.rawOnly ? 'Build and connect' : 'Set up this production cell'}</h3>${b.rawOnly ? `<p><strong>Research:</strong> ${b.requires.length ? b.requires.map(id => esc(id.replaceAll('-', ' '))).join(' · ') : 'Starting Nauvis technology'}. No robots required.</p>${b.researchBook ? `<p><a class="source-link" href="${esc(b.researchBook)}" download>Download the ${esc(b.unlockName)} research pack ${svg('download')}</a></p>` : ''}<p><a class="source-link" href="${esc(previewURL(b))}" target="_blank" rel="noopener">Open the labeled layout ↗</a></p>` : ''}<ul>${b.setupNotes.map(note => `<li>${esc(note)}</li>`).join('')}</ul>${b.ports?.length ? `<p class="small">Fluid connections: ${b.ports.map(p => esc(name(p.fluid)) + ' (' + esc(p.type) + ')').join(' · ')}</p>` : ''}</section>` : ''}${b.rawOnly ? `<details class="explorer-details"><summary>${b.rawOnly ? 'How this module is built' : 'Changes from the original design'}</summary><ul>${b.changes.map(change => `<li>${esc(change)}</li>`).join('')}</ul><a class="source-link" href="${esc(b.validation.report)}" target="_blank" rel="noopener">Read the native test report ↗</a></details>` : ''}<h3 class="explainer-heading">What goes in. What happens. What comes out.</h3><div class="production-flow blueprint-flow">${column('01 / SUPPLY FROM OUTSIDE', a.inputs, a.serviceInputs)}${column('02 / MADE & CIRCULATED INSIDE', a.internal, [], 'middle')}${column('03 / OUTPUTS & SERVICES', productsOf(b), a.serviceOutputs, 'finished')}</div>
      ${a.seeds.length ? `<div class="notice amber-notice"><div><strong>Startup stock / circulating ingredients</strong><div class="token-wrap">${tokens(a.seeds, Infinity, true)}</div><p>Supply an initial charge and keep it circulating. Per-craft quantities below are not a fill-volume estimate.</p></div></div>` : ''}
      <div class="analysis-notes">${a.notes.map(n => `<p>${esc(n)}</p>`).join('')}${a.missing.length ? `<p class="amber-text">Unavailable recipes: ${a.missing.map(esc).join(', ')}</p>` : ''}</div>
      <details class="explorer-details"><summary>Construction materials <span>${b.entries.length} item / quality pairs · ${number(b.entries.reduce((n,r) => n + r.count, 0))} items for building the layout</span></summary>${b.isBook ? '<p class="amber-text">Includes every design in the book, including alternatives.</p>' : ''}${b.excluded.length ? `<p class="amber-text">Unavailable or automatic entities excluded: ${b.excluded.map(esc).join(', ')}</p>` : ''}<div class="material-list">${b.entries.map(r => `<div>${image(r.id)}<span>${esc(name(r.id))}<small>${esc(r.quality)}</small></span><b>${number(r.count)}</b></div>`).join('')}</div><button class="button primary" data-action="pack-blueprint" data-id="${b.id}">${svg('box')} Add construction materials to crate builder</button><p class="small muted">Entities, tiles, and requested modules/items. Operating ingredients and fluids are separate.</p></details>
      ${operatingGuide(b)}
      ${a.recipes.length ? `<details class="explorer-details"><summary>Recipe breakdown <span>${a.recipes.length} recipes · exact ingredients per craft</span></summary>${a.recipes.map(({ id, count }) => recipeMarkup(recipes.get(id), count)).join('')}</details>` : ''}
      ${blueprintRates(b)}
      <div class="source-links">${b.sources.map(url => `<a class="source-link" href="${esc(url)}" target="_blank" rel="noopener">${b.collection === 'Autosaved' ? 'Original blueprint collection by Autosaved ↗' : esc(url.replace('sources/', ''))}</a>`).join('')}</div></div>`);
  }
  function plan() {
    return globalThis.FactorioProduction.planProduction(s.targets, production, { supplied: s.boundary === 'plates' ? ['iron-plate', 'copper-plate', 'steel-plate', 'stone-brick', 'heavy-oil', 'light-oil', 'petroleum-gas'] : s.boundary === 'blueprint' ? s.supplied : [] });
  }
  function quantityRows(rows, mode) {
    return rows.map(r => `<div class="flow-item">${image(r.id)}<span><button class="product-drill" data-action="product-path" data-id="${esc(r.id)}" title="See recipes and matching blueprints">${esc(name(r.id))}</button><small>${goods.get(r.id)?.type === 'fluid' ? 'Fluid units · use pipes / tanks' : mode === 'middle' ? 'Made across this plan' : 'Items'}${mode === 'middle' ? ` · ${number(r.used)} used internally` : ''}</small></span><b>${number(r.count)}</b></div>`).join('') || '<p class="small muted">No materials at this stage.</p>';
  }
  function productionPage() {
    let result, error = '';
    try { result = plan(); } catch (e) { error = e.message; }
    const blueprintMatches = library.blueprints.filter(b => !b.isBook && productsOf(b).some(id => s.targets.some(t => t.id === id))).slice(0, 6);
    return `${heading('RAW → INTERMEDIATE → READY TO BUILD', 'Production planner', 'Choose your finished goods. Trace every shared ingredient back to its source.', '<a class="button secondary" href="#blueprints">Browse blueprints '+svg('arrow')+'</a>')}${s.planNote ? `<div class="notice plan-context">${esc(s.planNote)}</div>` : ''}<div class="planner-presets"><span class="micro-label">START WITH</span>${[['solar', 'solar-panel', 'Solar expansion'], ['robots', 'construction-robot', 'Robot network'], ['circuits', 'processing-unit', 'Circuit production']].map(([id, icon, title]) => `<button class="feature-link" data-action="production-preset" data-id="${id}">${image(icon)}${title}</button>`).join('')}</div><section class="planner-controls"><div class="section-heading"><div><span class="eyebrow">YOUR PRODUCTION ORDER</span><h2>What do you want to make?</h2></div><button class="text-button" data-action="production-clear">Clear order</button></div><div class="target-list">${s.targets.map((t, i) => `<div class="target-row">${image(t.id)}<span>${esc(name(t.id))}</span><label class="sr-only" for="target-${i}">Quantity of ${esc(name(t.id))}</label><input id="target-${i}" data-production-quantity="${i}" type="number" min="1" max="1000000" step="1" value="${esc(t.count)}"><button class="icon-button" data-action="production-remove" data-id="${i}" aria-label="Remove ${esc(name(t.id))}">${svg('close')}</button></div>`).join('')}</div><form id="production-add-form" class="product-add"><label class="sr-only" for="production-item">Choose a product</label><input id="production-item" class="text-input" list="production-options" placeholder="Add another product by name or ID…" autocomplete="off"><datalist id="production-options">${[...goods.values()].map(i => `<option value="${esc(i.id)}">${esc(i.name)}</option>`).join('')}</datalist><button class="button secondary" type="submit">${svg('plus')} Add product</button></form>${s.error ? `<p class="validation-error" role="alert">${esc(s.error)}</p>` : ''}<div class="planner-boundary"><label for="production-boundary">Start the chain from</label><select id="production-boundary"><option value="raw" ${s.boundary === 'raw' ? 'selected' : ''}>Raw resources · ores, water & crude oil</option><option value="plates" ${s.boundary === 'plates' ? 'selected' : ''}>Processed supply · plates & refinery products</option>${s.supplied.length ? `<option value="blueprint" ${s.boundary === 'blueprint' ? 'selected' : ''}>Blueprint inputs · ${esc(s.fromBlueprint)}</option>` : ''}</select></div></section>${error ? `<div class="notice amber-notice" role="status">${esc(error)}</div>` : ''}${result ? `<div class="plan-summary"><span>${result.targets.length} finished products</span><span>${result.steps.length} recipe steps</span><span>Whole batches · shared ingredients combined</span><button class="text-button" data-action="production-export">${svg('download')} Export plan</button></div><div class="production-flow planner-flow"><section class="flow-column"><div class="stage-heading"><span>01</span><div><h2>${s.boundary === 'raw' ? 'Raw & supplied inputs' : 'Supplied inputs'}</h2><p>Bring these into the chain</p></div></div>${quantityRows(result.raw, 'raw')}<button class="button secondary full" data-action="pack-production" data-id="raw">${svg('box')} Pack solid inputs</button><p class="small muted">Fluids stay in the list and require pipes or tanks.</p></section><section class="flow-column middle"><div class="stage-heading"><span>02</span><div><h2>Intermediates</h2><p>Click a material for recipes & blueprints</p></div></div>${quantityRows(result.intermediates, 'middle')}</section><section class="flow-column finished"><div class="stage-heading"><span>03</span><div><h2>Finished goods</h2><p>Your requested quantities</p></div></div>${quantityRows(result.targets, 'final')}<button class="button primary full" data-action="pack-production" data-id="targets">${svg('box')} Pack finished items</button><p class="small muted">Packing generates a command to spawn supplies. It does not run this manufacturing chain.</p>${result.surplus.length ? `<details class="surplus-details"><summary>Batch surplus & byproducts · ${result.surplus.length}</summary>${quantityRows(result.surplus, 'surplus')}<p class="small muted">Store or consume these extras. Oil refining needs room for every output to keep running.</p></details>` : ''}</section></div><div class="planner-assumptions"><strong>How to read this plan</strong><p>Normal-quality material budget using standard recipes from your installed game. Whole crafts are rounded up after combining shared demand. Advanced oil processing supplies all three oil products together; cracking is not included. Extra products appear as surplus.</p><p>This is a baseline before machine, module, beacon, research, and productivity bonuses. Power, burner fuel, spoilage, mining, travel, and machine throughput are not calculated. Surface restrictions and required research still apply; this does not prove a blueprint can sustain a production rate.</p>${result.external.length ? `<p class="amber-text">Supply separately: ${result.external.map(id => esc(name(id))).join(', ')}. No deterministic standard route is selected for these resources; planet-specific or random-yield routes need a separate process.</p>` : ''}</div><details class="explorer-details"><summary>Follow the recipes in production order <span>${result.steps.length} steps · open each recipe for its inputs and outputs</span></summary><ol class="recipe-steps">${result.steps.map(step => `<li><button data-action="production-recipe" data-id="${esc(step.id)}"><span>${esc(name(step.id))}</span><b>${number(step.crafts)} crafts</b>${svg('arrow')}</button></li>`).join('')}</ol></details>${blueprintMatches.length ? `<section class="suggested-blueprints"><div class="section-heading"><h2>Blueprints for these products</h2><span class="small muted">Compare operating inputs before building</span></div><div class="suggested-grid">${blueprintMatches.map(b => `<button class="suggested-build" data-action="blueprint-details" data-id="${b.id}">${image(productsOf(b).find(id => s.targets.some(t => t.id === id)))}<span><strong>${esc(b.name)}</strong><small>${esc(b.category)} · ${b.entityCount} entities</small></span>${svg('arrow')}</button>`).join('')}</div></section>` : ''}` : ''}`;
  }
  function goProduction() { save(); document.querySelector('#modal').close(); location.hash = 'production'; renderPage(); }
  async function handleClick(action, id) {
    if (action === 'starter-unlock') {
      const blueprint = library.blueprints.find(b => b.starter && b.unlock === id);
      if (blueprint) Object.assign(s, { source: STARTER_COLLECTION, category: blueprint.category, query: '', kind: 'All', direction: 'outputs', page: 0 });
    } else if (action === 'explore-feature') {
      Object.assign(s, { query: '', category: 'All', kind: 'All', direction: 'all', source: 'All', page: 0 });
      if (id === 'early-game') Object.assign(s, {source: STARTER_COLLECTION, direction: 'outputs'});
      if (id === 'transport') Object.assign(s, {source: TRANSPORT_COLLECTION, direction: 'outputs'});
      if (id === 'science-factories') Object.assign(s, {source: SCIENCE_COLLECTION, direction: 'outputs'});
      if (id === 'power-workshops') Object.assign(s, {source: POWER_COLLECTION, direction: 'outputs'});
      if (id === 'solar') { s.query = 'solar-panel'; s.direction = 'outputs'; }
      if (id === 'robots') { s.query = 'Robots'; s.category = 'Base'; }
      if (id === 'power') s.kind = 'Power';
      if (id === 'science') s.category = 'Science';
    } else if (action === 'blueprint-page') { s.page += Number(id); document.querySelector('#main').scrollIntoView({ behavior: 'instant' }); }
    else if (action === 'plan-blueprint') {
      const b = displayedBlueprint?.id === id ? displayedBlueprint : library.blueprints.find(b => b.id === id);
      s.targets = productsOf(b).filter(id => goods.has(id)).map(id => ({ id, count: 1 }));
      track('production_plan', 'products');
      s.supplied = b.analysis.inputs; s.boundary = 'blueprint'; s.fromBlueprint = b.name; s.planNote = ''; s.error = '';
      goProduction(); return true;
    } else if (action === 'plan-blueprint-inputs' || action === 'plan-supply') {
      const b = action === 'plan-blueprint-inputs' ? (displayedBlueprint?.id === id ? displayedBlueprint : library.blueprints.find(b => b.id === id)) : null;
      s.targets = b ? supplyTargets(b).map(t => ({...t})) : [supplyBatch(id)];
      track('production_plan', 'supplies');
      s.supplied = []; s.boundary = 'raw'; s.fromBlueprint = ''; s.error = '';
      s.planNote = b?.startup ? `Operating supply plan for ${b.name}. Starts with tested stock: ${b.startup.targets.map(t => number(t.count) + ' ' + name(t.id)).join(' and ')}. Adjust as needed; fuel is consumed and coolant circulates. ${b.startup.note}` : `Operating supply plan${b ? ' for ' + b.name : ': ' + name(id)}. Start with one recipe batch per supply, then set the stock you want. Quantities are a material budget, not a production-rate estimate.`;
      goProduction(); return true;
    } else if (action === 'production-preset') {
      const kits = { solar: [['solar-panel', 100], ['accumulator', 84], ['substation', 8]], robots: [['construction-robot', 50], ['logistic-robot', 50], ['roboport', 4], ['passive-provider-chest', 8], ['storage-chest', 8]], circuits: [['electronic-circuit', 100], ['advanced-circuit', 100], ['processing-unit', 100]] };
      track('production_plan', id);
      s.targets = kits[id].map(([id, count]) => ({ id, count })); s.boundary = 'raw'; s.planNote = ''; s.error = ''; save();
    } else if (action === 'production-remove') { s.targets.splice(Number(id), 1); save(); }
    else if (action === 'production-clear') { s.targets = []; s.planNote = ''; save(); }
    else if (action === 'product-path') {
      track('product_view', id);
      const recipe = recipes.get(production.defaults[id]) || recipes.get(atlas.coverage.items.find(i => i.id === id)?.recipes[0]);
      const itemCoverage = atlas.coverage.items.find(i => i.id === id);
      const builds = itemCoverage ? itemCoverage.builds.slice(0, 12).map(id => byId.get(id)) : library.blueprints.filter(b => !b.isBook && productsOf(b).includes(id)).slice(0, 12);
      showModal(name(id), `<p>${recipe ? 'The standard recipe used for this material. The blueprint suggestions below may use different supply chains.' : 'This material is supplied from outside the selected recipe chain. Mining, collection, or a separate process may be needed.'}</p>${recipe ? recipeMarkup(recipe) : ''}<button class="button secondary" data-action="plan-supply" data-id="${esc(id)}">Plan from raw resources ${svg('arrow')}</button><h3 class="explainer-heading">Blueprints that produce this item</h3>${builds.length ? `<div class="suggested-grid">${builds.map(b => `<button class="suggested-build" data-action="blueprint-details" data-id="${b.id}">${image(id)}<span><strong>${esc(b.name)}</strong><small>${esc(b.category)}</small></span>${svg('arrow')}</button>`).join('')}</div>` : '<p class="small muted">No configured manufacturing output matches this item. Browse the Resources and Mining sections for extraction and smelting layouts.</p>'}`);
      return true;
    }
    else if (action === 'production-recipe') { showModal(name(id), recipeMarkup(recipes.get(id))); return true; }
    else if (action === 'production-export') { download('factorio-production-plan.json', JSON.stringify({ version: 1, game: catalog.version, boundary: s.boundary, assumptions: 'Normal quality; no productivity, cracking, power, fuel, spoilage, or throughput. Whole recipe batches.', ...plan() }, null, 2)); return true; }
    else if (action === 'pack-production') {
      const rows = plan()[id], solids = rows.filter(r => goods.get(r.id)?.type !== 'fluid' && catalog.items.some(i => i.id === r.id));
      const fluids = rows.filter(r => goods.get(r.id)?.type === 'fluid');
      if (!solids.length) { notify('These inputs are fluids. Supply them with pipes and tanks.'); return true; }
      const result = addRows(solids.map(r => ({ id: r.id, count: Math.ceil(r.count), quality: 'normal' })));
      if (result === false) return true;
      track('crate_pack', id);
      location.hash = 'crates';
      notify(`Added ${solids.length} solid item types.${fluids.length ? ` ${fluids.length} fluids remain in your production plan; use pipes or tanks.` : ''}`);
      return true;
    } else return false;
    renderPage(); return true;
  }
  function handleInput(field) {
    if (field.id === 'coverage-search') { s.coverageQuery = field.value; renderPage(); return true; }
    if (field.id === 'blueprint-search') { s.query = field.value; s.page = 0; renderPage(); return true; }
    if (field.dataset.productionQuantity != null) { s.targets[Number(field.dataset.productionQuantity)].count = field.value === '' ? '' : Number(field.value); save(); renderPage(); return true; }
    return false;
  }
  function handleChange(field) {
    const mapping = { 'coverage-group': 'coverageGroup', 'blueprint-category': 'category', 'blueprint-source': 'source', 'blueprint-kind': 'kind', 'blueprint-direction': 'direction', 'production-boundary': 'boundary' };
    if (!mapping[field.id]) return false;
    if (field.id === 'production-boundary' && ['raw', 'plates'].includes(field.value)) track('production_plan', field.value);
    s[mapping[field.id]] = field.value; s.page = 0; save(); renderPage(); return true;
  }
  document.addEventListener('submit', event => {
    if (event.target.id !== 'production-add-form') return;
    event.preventDefault();
    const value = document.querySelector('#production-item').value.trim();
    const item = [...goods.values()].find(i => i.id === value || i.name.toLowerCase() === value.toLowerCase());
    if (!item) s.error = 'Choose an available item or fluid from the list.';
    else if (s.targets.length >= 100) s.error = 'Use 100 products or fewer per plan.';
    else { const old = s.targets.find(t => t.id === item.id); if (old) old.count = Math.min(1000000, Number(old.count) + 1); else s.targets.push({ id: item.id, count: 1 }); s.error = ''; save(); track('production_plan', 'custom'); }
    renderPage(); document.querySelector('#production-item')?.focus();
  });
  function clearDisplayedBlueprint() { displayedBlueprint = undefined; }
  return { blueprintsPage, blueprintDialog, productionPage, coveragePage, handleClick, handleInput, handleChange, refreshBlueprints, clearDisplayedBlueprint };
}
globalThis.FactorioExplorer = { create };
})();
